import { z } from "zod";
import data from "@/../content/media-registry.json";
import { CLIP_IDS, type ClipId } from "@/core/clips/clips";

/** Where a media comes from: recorded by the e2e tests, made by the founder, or generated by a model. */
export const MediaOrigin = { Test: "test", Founder: "founder", Generated: "generated" } as const;
export type MediaOrigin = (typeof MediaOrigin)[keyof typeof MediaOrigin];

const entry = z.object({
  id: z.enum(CLIP_IDS),
  origin: z.enum([MediaOrigin.Test, MediaOrigin.Founder, MediaOrigin.Generated]),
  owner: z.string().min(1),
  location: z.string().min(1),
  /** Why this media serves its sections: the action it shows and its result. */
  reason: z.string().min(1).optional(),
  /** The founder said yes to this media on a page (required for anything that is not a test recording). */
  founderYes: z.boolean().optional(),
  /** Why it must not be shown on the public export (the retired code name on screen…). */
  blocked: z.string().min(1).optional(),
  uses: z.array(z.object({ page: z.string().min(1), role: z.string().min(1) })),
});
const registry = z.object({ media: z.array(entry) });
export type MediaRegistry = z.infer<typeof registry>;
type MediaEntry = MediaRegistry["media"][number];

/** The registry of the pages' media, parsed once: `content/media-registry.json` (krizaka-internal#4635). */
export const MEDIA_REGISTRY: MediaRegistry = registry.parse(data);

/** A test recording may be shown; anything else needs the founder's yes; a blocked one never. */
const showable = (m: MediaEntry): boolean =>
  m.blocked === undefined && (m.origin === MediaOrigin.Test || m.founderYes === true);

/** The clips of one page section, by role, in the registry's order: only those that may be shown. */
export function sectionMedia(page: string, role: string, media: MediaRegistry = MEDIA_REGISTRY): ClipId[] {
  return media.media
    .filter((m) => showable(m) && m.uses.some((u) => u.page === page && u.role === role))
    .map((m) => m.id);
}

/**
 * Whether the public export may show a clip anywhere (a page's own `clip`, as the docs index names it): only a clip the
 * registry lists as showable. Fails closed: a clip the registry does not know is not shown.
 */
export function clipPublishable(id: ClipId, media: MediaRegistry = MEDIA_REGISTRY): boolean {
  const m = media.media.find((e) => e.id === id);
  return m !== undefined && showable(m);
}
